#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. Shader-only effect: every layer is a particle carrier, Custom1.x = progress, Custom1.y = seed.
    // Layer IDs follow Docs/VFX/FireballImpact/Plan.md. The prefab is rebuilt from this script: edit here, not in the Inspector.
    public static class FireballImpactBuild
    {
        const string Effect = "FireballImpact";
        const string Root = "Assets/VFX/" + Effect;
        const string NoiseTex = "Assets/VFX/_Shared/Textures/Noise/T_Noise_Smooth.png";

        // Timing (s)
        const float FallLife = 0.9f;      // L1; impact happens here
        const float FallAngle = 60f;      // degrees below horizontal, falling to the right
        const float FallDist = 4.5f;
        const float HalfH = 1.25f;        // L1 quad half-height (m) -> head radius 0.4 * 1.25 = 0.5 m (1 m ball)
        static readonly Vector3 Impact = new Vector3(0f, 0.4f, 0f);

        static Color Hdr(float r, float g, float b, float k) => new Color(r, g, b) * k;

        [MenuItem("VFX/FireballImpact/Build")]
        public static void Build()
        {
            Debug.Log("[FireballImpact] Build started");
            if (!ConfirmSceneSwitch()) { Debug.LogWarning("[FireballImpact] Build cancelled at the save-scene prompt."); return; }
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");

            var noise = MeteorBuild.ImportNoise(NoiseTex);
            string M(string layer, string blend) => Root + "/Materials/M_" + Effect + "_" + layer + "_" + blend + ".mat";

            // ---------------------------------------------------------------- materials
            var fireOuter = Hdr(0.55f, 0.06f, 0.02f, 1.6f);
            var fireMid = Hdr(1f, 0.38f, 0.06f, 2f);
            var fireCore = Hdr(1f, 0.92f, 0.6f, 2.5f);

            var matBall = Material(M("Ball", "Add"), VfxBlend.Additive, null, "VFX/FX/Meteor");
            matBall.SetTexture("_NoiseTex", noise);
            matBall.EnableKeyword("_USE_PARTICLE_DATA"); matBall.SetFloat("_UseParticle", 1);
            matBall.SetFloat("_Aspect", 3f);   // quad 7.5 x 2.5
            matBall.SetColor("_ColorOuter", fireOuter); matBall.SetColor("_ColorMid", fireMid); matBall.SetColor("_ColorCore", fireCore);

            var matBlast = Material(M("Blast", "Add"), VfxBlend.Additive, null, "VFX/FX/Blast");
            matBlast.SetTexture("_NoiseTex", noise);
            matBlast.EnableKeyword("_USE_PARTICLE_DATA"); matBlast.SetFloat("_UseParticle", 1);
            matBlast.EnableKeyword("_NO_RING"); matBlast.SetFloat("_NoRing", 1);
            matBlast.SetColor("_ColorOuter", fireOuter); matBlast.SetColor("_ColorMid", fireMid); matBlast.SetColor("_ColorCore", fireCore);

            var matRing = Material(M("Ring", "Add"), VfxBlend.Additive, null, "VFX/FX/Blast");
            matRing.SetTexture("_NoiseTex", noise);
            matRing.EnableKeyword("_USE_PARTICLE_DATA"); matRing.SetFloat("_UseParticle", 1);
            matRing.EnableKeyword("_RING_ONLY"); matRing.SetFloat("_RingOnly", 1);
            matRing.SetFloat("_RingRadius", 0.95f); matRing.SetFloat("_RingWidth", 0.07f);
            matRing.SetColor("_ColorOuter", Hdr(1f, 0.45f, 0.1f, 3f)); matRing.SetColor("_ColorMid", Hdr(1f, 0.6f, 0.15f, 3.5f)); matRing.SetColor("_ColorCore", Hdr(1f, 0.95f, 0.7f, 4f));
            matRing.SetFloat("_Band1", 0.2f);

            var matSmoke = Material(M("Smoke", "Alpha"), VfxBlend.Alpha, null, "VFX/FX/Smoke");
            matSmoke.SetTexture("_NoiseTex", noise);
            matSmoke.EnableKeyword("_USE_PARTICLE_DATA"); matSmoke.SetFloat("_UseParticle", 1);
            matSmoke.SetColor("_ColorLight", new Color(0.62f, 0.54f, 0.48f));
            matSmoke.SetColor("_ColorDark", new Color(0.2f, 0.15f, 0.14f));

            var matScorch = Material(M("Scorch", "Alpha"), VfxBlend.Alpha, null, "VFX/FX/Smoke");
            matScorch.SetTexture("_NoiseTex", noise);
            matScorch.EnableKeyword("_USE_PARTICLE_DATA"); matScorch.SetFloat("_UseParticle", 1);
            matScorch.SetColor("_ColorLight", new Color(0.45f, 0.14f, 0.04f));
            matScorch.SetColor("_ColorDark", new Color(0.03f, 0.02f, 0.02f));
            matScorch.SetFloat("_Erosion", 0.4f); matScorch.SetFloat("_Grow", 0.35f); matScorch.SetFloat("_Opacity", 0.95f);
            matScorch.SetVector("_LightDir", new Vector4(0f, 0f, 0f, 0f));

            var matSpark = Material(M("Spark", "Add"), VfxBlend.Additive, null, "VFX/FX/Spark");
            matSpark.EnableKeyword("_USE_PARTICLE_DATA"); matSpark.SetFloat("_UseParticle", 1);
            matSpark.SetColor("_ColorTail", Hdr(1f, 0.3f, 0.04f, 2f)); matSpark.SetColor("_ColorHead", Hdr(1f, 0.9f, 0.55f, 3f));

            var root = new GameObject("VFX_" + Effect);

            // ---------------------------------------------------------------- L1 fireball + tail (flies, head lands on Impact at t = FallLife)
            float a = FallAngle * Mathf.Deg2Rad;
            var dir = new Vector3(Mathf.Cos(a), -Mathf.Sin(a), 0f);              // flight direction, falling to the right
            float headOff = 1.9f * HalfH;                                         // _HeadX (-1.9) in height units
            var endCenter = Impact - dir * headOff;
            var l1 = Particle(root.transform, "L1_Fireball", matBall, lifetime: FallLife, size: 2f * HalfH);
            l1.transform.localPosition = endCenter - dir * FallDist;
            var m1 = l1.main;
            m1.startSize3D = true;
            m1.startSizeX = 6f * HalfH; m1.startSizeY = 2f * HalfH; m1.startSizeZ = 1f;
            // head is at the quad's -X side; billboard rotation is clockwise, so head direction (-cos t, -sin t) needs t = 180 - FallAngle ccw
            m1.startRotation = -(180f - FallAngle) * Mathf.Deg2Rad;
            var v1 = l1.velocityOverLifetime;
            v1.enabled = true; v1.space = ParticleSystemSimulationSpace.Local;
            var vel = dir * (FallDist / FallLife);
            v1.x = vel.x; v1.y = vel.y; v1.z = 0f;
            MeteorBuild.FxProgress(l1, Curve(0f, 0f, 1f, 1f));

            // ---------------------------------------------------------------- L2 flash + exploding fireball (upright)
            var l2 = Particle(root.transform, "L2_Blast", matBlast, lifetime: 0.7f, size: 6f);
            l2.transform.localPosition = new Vector3(0f, 1.3f, 0f);
            var m2 = l2.main; m2.startDelay = FallLife;
            MeteorBuild.FxProgress(l2, Curve(0f, 0f, 1f, 1f));

            // ---------------------------------------------------------------- L3 shockwave ring (flat on the ground)
            var l3 = Particle(root.transform, "L3_Ring", matRing, lifetime: 0.6f, size: 6f);
            l3.transform.localPosition = new Vector3(0f, 0.03f, 0f);
            l3.GetComponent<ParticleSystemRenderer>().renderMode = ParticleSystemRenderMode.HorizontalBillboard;
            l3.GetComponent<ParticleSystemRenderer>().sortingFudge = 3f;
            var m3 = l3.main; m3.startDelay = FallLife;
            MeteorBuild.FxProgress(l3, Curve(0f, 0f, 1f, 1f));

            // ---------------------------------------------------------------- L6 scorch mark (flat on the ground)
            var l6 = Particle(root.transform, "L6_Scorch", matScorch, lifetime: 0.85f, size: 3f);
            l6.transform.localPosition = new Vector3(0f, 0.02f, 0f);
            l6.GetComponent<ParticleSystemRenderer>().renderMode = ParticleSystemRenderMode.HorizontalBillboard;
            l6.GetComponent<ParticleSystemRenderer>().sortingFudge = 4f;
            var m6 = l6.main; m6.startDelay = FallLife + 0.05f;
            MeteorBuild.FxProgress(l6, Curve(0f, 0f, 1f, 1f));

            // ---------------------------------------------------------------- L4 smoke (3 puffs rising)
            var l4 = Particle(root.transform, "L4_Smoke", matSmoke, lifetime: 0.6f, size: 2f);
            l4.transform.localPosition = new Vector3(0f, 0.6f, 0f);
            Burst(l4, 3);
            var m4 = l4.main;
            m4.startDelay = FallLife + 0.3f;     // after the fireball peaks, so it does not cover the flash
            m4.startSize = new ParticleSystem.MinMaxCurve(1.8f, 2.6f);
            m4.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            var s4 = l4.shape; s4.enabled = true; s4.shapeType = ParticleSystemShapeType.Sphere; s4.radius = 0.7f;
            var v4 = l4.velocityOverLifetime; v4.enabled = true; v4.space = ParticleSystemSimulationSpace.Local;
            v4.x = 0f; v4.y = new ParticleSystem.MinMaxCurve(1.2f, 2f); v4.z = 0f;
            MeteorBuild.FxProgress(l4, Curve(0f, 0f, 1f, 1f));
            l4.GetComponent<ParticleSystemRenderer>().sortingFudge = -1f;

            // ---------------------------------------------------------------- L5 sparks (stretched billboards flying out)
            var l5 = Particle(root.transform, "L5_Sparks", matSpark, lifetime: 0.6f, size: 0.14f);
            l5.transform.localPosition = new Vector3(0f, 0.5f, 0f);
            Burst(l5, 14);
            var m5 = l5.main;
            m5.startDelay = FallLife;
            m5.startLifetime = new ParticleSystem.MinMaxCurve(0.4f, 0.7f);
            m5.startSpeed = new ParticleSystem.MinMaxCurve(4f, 9f);
            m5.startSize = new ParticleSystem.MinMaxCurve(0.1f, 0.18f);
            m5.gravityModifier = 1.2f;
            var s5 = l5.shape; s5.enabled = true; s5.shapeType = ParticleSystemShapeType.Hemisphere; s5.radius = 0.15f;
            s5.rotation = new Vector3(-90f, 0f, 0f);   // hemisphere opens upward
            var r5 = l5.GetComponent<ParticleSystemRenderer>();
            r5.renderMode = ParticleSystemRenderMode.Stretch;
            r5.velocityScale = 0.05f; r5.lengthScale = 2.5f;
            MeteorBuild.FxProgress(l5, Curve(0f, 0f, 1f, 1f));

            // ---------------------------------------------------------------- save, validate, preview, demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.45f, 0.7f, 0.9f, 1.0f, 1.15f, 1.35f, 1.6f, 1.8f }, new Vector3(0f, 4.6f, -5.6f), new Vector3(0f, 1.1f, 0f));
        }

        public static void BuildBatch() => RunBatch(Build);
    }
}
#endif
